create or replace function game_rank_private.fold(p_text text) returns text language sql immutable set search_path='' as $$ select lower(translate(normalize(coalesce(p_text,''),NFC),'ÀÁÂÃÄÅÈÉÊËÌÍÎÏÒÓÔÕÖÙÚÛÜÝàáâãäåèéêëìíîïòóôõöùúûüýÿĀāĂăĄąĒēĔĕĖėĘęĚěĨĩĪīĬĭĮįİŌōŎŏŐőŨũŪūŬŭŮůŰűŲųŶŷŸƠơƯưǍǎǏǐǑǒǓǔǕǖǗǘǙǚǛǜǞǟǠǡǪǫǬǭǺǻȀȁȂȃȄȅȆȇȈȉȊȋȌȍȎȏȔȕȖȗȦȧȨȩȪȫȬȭȮȯȰȱȲȳḀḁḔḕḖḗḘḙḚḛḜḝḬḭḮḯṌṍṎṏṐṑṒṓṲṳṴṵṶṷṸṹṺṻẎẏẙẠạẢảẤấẦầẨẩẪẫẬậẮắẰằẲẳẴẵẶặẸẹẺẻẼẽẾếỀềỂểỄễỆệỈỉỊịỌọỎỏỐốỒồỔổỖỗỘộỚớỜờỞởỠỡỢợỤụỦủỨứỪừỬửỮữỰựỲỳỴỵỶỷỸỹđĐ','AAAAAAEEEEIIIIOOOOOUUUUYaaaaaaeeeeiiiiooooouuuuyyAaAaAaEeEeEeEeEeIiIiIiIiIOoOoOoUuUuUuUuUuUuYyYOoUuAaIiOoUuUuUuUuUuAaAaOoOoAaAaAaEeEeIiIiOoOoUuUuAaEeOoOoOoOoYyAaEeEeEeEeEeIiIiOoOoOoOoUuUuUuUuUuYyyAaAaAaAaAaAaAaAaAaAaAaAaEeEeEeEeEeEeEeEeIiIiOoOoOoOoOoOoOoOoOoOoOoOoUuUuUuUuUuUuUuYyYyYyYydD')) $$;

create or replace function game_rank_private.obj(v jsonb) returns jsonb language sql immutable set search_path='' as $$
 select case when jsonb_typeof(v)='object' then v else '{}'::jsonb end
$$;
create or replace function game_rank_private.arr(v jsonb) returns jsonb language sql immutable set search_path='' as $$
 select case when jsonb_typeof(v)='array' then v else '[]'::jsonb end
$$;
create or replace function game_rank_private.num(v jsonb,lo numeric,hi numeric, fallback numeric default 0)
returns numeric language sql immutable set search_path='' as $$
 select case when jsonb_typeof(v)='number' then greatest(lo,least(hi,(v#>>'{}')::numeric)) else fallback end
$$;
create or replace function game_rank_private.total(v jsonb) returns bigint language sql immutable set search_path='' as $$
 select least(10000000,coalesce(sum(floor(game_rank_private.num(value,0,1000000))),0))::bigint
 from jsonb_each(game_rank_private.obj(v))
$$;
create or replace function game_rank_private.entitled(u uuid,item text) returns boolean
language plpgsql stable set search_path='' as $$
declare allowed boolean := false;
begin
 if to_regclass('public.premium_entitlements') is not null then
  execute 'select exists(select 1 from public.premium_entitlements where user_id=$1 and item_id=$2)' into allowed using u,item;
 end if;
 return allowed;
end $$;
create or replace function game_rank_private.visible(u uuid) returns boolean
language plpgsql stable set search_path='' as $$
declare allowed boolean := true;
begin
 if not exists(select 1 from auth.users where id=u and (banned_until is null or banned_until<=current_timestamp)) then return false; end if;
 if to_regclass('public.game_account_blocks') is not null then
  execute 'select not exists(select 1 from public.game_account_blocks where user_id=$1)' into allowed using u;
 end if;
 return allowed;
end $$;

-- Projection whitelist: neither the bag, wallet, email, account login nor the raw save is public.
create or replace function game_rank_private.project(u uuid,snapshot jsonb,changed timestamptz) returns jsonb
language plpgsql stable set search_path='' as $$
declare
 p jsonb := game_rank_private.obj(snapshot->'player');
 a jsonb := game_rank_private.obj(p->'adventure');
 life jsonb := game_rank_private.obj(p->'life');
 catalog jsonb; base jsonb; hero jsonb; definition jsonb; bonus jsonb; enhanced jsonb;
 hero_id text; sex text; name text; sect text; title text; realm text;
 lvl integer; realm_idx integer; child boolean; reputation bigint; contribution bigint; sect_rank integer;
 hp bigint; mp bigint; atk bigint; def bigint; power bigint;
 equipment jsonb := '[]'; companions jsonb := '[]'; skills jsonb := '[]'; mounts jsonb := '[]';
 slot text; raw_id text; item_id text; item jsonb; pet_id text; pet jsonb; pet_rank integer; evolution integer; active boolean;
 upgrade integer; pets_score bigint := 0; clears bigint := 0; boss_kills bigint := 0;
 selected jsonb := '[]'; defaults jsonb; sk text; skill jsonb; valid boolean;
 known_equipped boolean; q jsonb := game_rank_private.obj(snapshot->'quests');
begin
 select data into catalog from game_rank_private.balance where id;
 if catalog is null then raise exception 'LEADERBOARD_BALANCE_MISSING'; end if;
 if jsonb_typeof(p->'name') is distinct from 'string' or jsonb_typeof(p->'level') is distinct from 'number' then return null; end if;
 name := left(btrim(p->>'name'),24); if name='' then return null; end if;
 lvl := floor(game_rank_private.num(p->'level',1,(catalog->>'maxLevel')::numeric,1));
 base := catalog->'levels'->lvl::text; realm_idx := (base->>'realmIndex')::integer;
 child := p->>'origin'='vuong_gia_thon' and (p->'admitted') is distinct from 'true'::jsonb;
 child := coalesce(child,false);
 hero_id := p->>'heroId';
 if not (catalog->'heroes' ? coalesce(hero_id,'')) then hero_id := case when p->>'sex'='male' then 'wang_lam' else 'ly_mo_uyen' end; end if;
 hero := catalog->'heroes'->hero_id; sex := hero->>'sex';
 realm := case when child then 'Phàm Nhân' else base->>'realm' end;
 sect := case when a->>'boundSect'='linh_son_tong' then 'linh_son_tong' else 'dai_thua_vien' end;
 reputation := floor(game_rank_private.num(a->'reputation',0,10000000));
 contribution := floor(game_rank_private.num(a->'contribution',0,10000000));
 select coalesce(max(ord-1),0) into sect_rank from jsonb_array_elements(catalog->'sectRanks') with ordinality t(r,ord) where (r->>'reputation')::numeric<=reputation;
 if child then sect_rank:=0;end if;
 title := case when child then 'Thiếu niên Vương Gia Thôn' else (catalog->'sectRanks'->sect_rank->>'name') || ' · ' || (hero->>'school') end;
 hp := (base#>>'{stats,maxHp}')::bigint; mp := (base#>>'{stats,maxMp}')::bigint;
 atk := (base#>>'{stats,atk}')::bigint; def := (base#>>'{stats,def}')::bigint;
 for slot in select jsonb_array_elements_text(catalog->'slots') loop
  raw_id := game_rank_private.obj(p->'equipment')->>slot; item_id := split_part(coalesce(raw_id,''),'~',1);
  definition := catalog->'items'->item_id;
  if definition is null or definition->>'slot'<>slot then continue; end if;
  if item_id='tien_phap_bao' and (raw_id<>item_id or not game_rank_private.entitled(u,item_id)) then continue; end if;
  upgrade := floor(game_rank_private.num(game_rank_private.obj(a->'enhancements')->raw_id,0,12));
  bonus := definition->'bonus'; enhanced := definition->'enhanced'->upgrade;
  hp := hp+coalesce((bonus->>'hp')::bigint,0)+(enhanced->>'hp')::bigint;
  atk := atk+coalesce((bonus->>'atk')::bigint,0)+(enhanced->>'atk')::bigint;
  def := def+coalesce((bonus->>'def')::bigint,0)+(enhanced->>'def')::bigint;
  equipment := equipment || jsonb_build_array(jsonb_build_object('slot',slot,'id',item_id,'enhancement',upgrade));
 end loop;
 for pet_id,pet in select key,value from jsonb_each(game_rank_private.obj(life->'companions')) loop
  definition := catalog->'companions'->pet_id;
  if definition is null or jsonb_typeof(pet->'rank') is distinct from 'number' then continue; end if;
  pet_rank := floor(game_rank_private.num(pet->'rank',1,5,1));
  evolution := floor(game_rank_private.num(game_rank_private.obj(a->'evolution')->pet_id,0,2));
  active := coalesce(life->>'companion'=pet_id,false);
  pets_score := pets_score+pet_rank+evolution*3;
  if active then
   hp := hp+round((definition->>'hp')::numeric*pet_rank*(1+0.5*evolution));
   atk := atk+round((definition->>'atk')::numeric*pet_rank*(1+0.5*evolution));
   def := def+round((definition->>'def')::numeric*pet_rank*(1+0.5*evolution));
  end if;
  if not child then companions := companions || jsonb_build_array(jsonb_build_object('id',pet_id,'rank',pet_rank,'evolution',evolution,'active',active)); end if;
 end loop;
 if life->>'artifact'='phap_bao_ngoc' then hp:=hp+100;def:=def+12;end if;
 power := floor(hp*0.2::double precision+mp*0.1::double precision+atk*5+def*4+0.15*500+0.5);
 for item_id,item in select key,value from jsonb_each(game_rank_private.obj(p#>'{dungeons,clears}')) loop
  if catalog->'dungeons' ? item_id then clears := least(10000000,clears+floor(game_rank_private.num(item,0,1000000))); end if;
 end loop;
 boss_kills := floor(game_rank_private.num(p#>'{achievements,bossKills}',0,10000000));
 -- A bounded, validated loadout and public skill levels; secret books themselves stay private.
 defaults := hero->'loadout';
 if not (p ? 'heroId') then defaults := '["basic","bang_tam_tram","phi_kiem","han_bang_tran"]'::jsonb || defaults; end if;
 if not child then
  selected := '["basic"]';
  for sk in select jsonb_array_elements_text(game_rank_private.arr(coalesce(p->'skillLoadout',defaults)) || defaults || '["than_phap"]'::jsonb) loop
   skill := catalog->'skills'->sk;
   valid := skill is not null and (skill->>'hero' is null or skill->>'hero'=hero_id)
    and (skill->>'character' is null or ((skill->>'character'=sex) and (skill->>'character'<>'male' or hero_id='wang_lam')))
    and lvl>=coalesce((skill->>'unlockLevel')::integer,1)
    and (skill->>'secret'<>'true' or game_rank_private.arr(a->'learnedSecrets') ? sk);
   if not valid then continue; end if;
   if sk<>'than_phap' and not(selected ? sk) and jsonb_array_length(selected)<7 then selected := selected || jsonb_build_array(sk); end if;
  end loop;
  for sk,skill in select key,value from jsonb_each(catalog->'skills') loop
   valid := (skill->>'hero' is null or skill->>'hero'=hero_id)
    and (skill->>'character' is null or (skill->>'character'=sex and (skill->>'character'<>'male' or hero_id='wang_lam')))
    and lvl>=coalesce((skill->>'unlockLevel')::integer,1)
    and (skill->>'secret'<>'true' or game_rank_private.arr(a->'learnedSecrets') ? sk);
   if not valid then continue; end if;
   known_equipped := selected ? sk or sk='than_phap';
   skills := skills || jsonb_build_array(jsonb_build_object('id',sk,'level',floor(game_rank_private.num(game_rank_private.obj(p->'skills')->sk,1,10,1)),'equipped',known_equipped));
  end loop;
  -- Keep loadout order in the overview and stay within the existing inspection parser cap.
  select coalesce(jsonb_agg(e order by case when selected ? (e->>'id') then (select ord from jsonb_array_elements_text(selected) with ordinality t(id,ord) where id=e->>'id') when e->>'id'='than_phap' then 8 else 100 end,e->>'id'),'[]'::jsonb)
   into skills from (select value e from jsonb_array_elements(skills) order by (value->>'equipped')::boolean desc,value->>'id' limit 60) s;
  if realm_idx>=1 or q#>>'{main_4,status}'='done' then mounts := mounts || jsonb_build_array(jsonb_build_object('id','sword','active',coalesce(p#>>'{immortal,mount}'='sword',false),'speed',1.45+realm_idx*0.01,'showMount',realm_idx<6));end if;
  if q#>>'{main_hac,status}'='done' then mounts := mounts || jsonb_build_array(jsonb_build_object('id','crane','active',coalesce(p#>>'{immortal,mount}'='crane',false),'speed',1.7+realm_idx*0.01,'showMount',true));end if;
 end if;
 return jsonb_build_object('id',u::text,'name',name,'contribution',contribution,'reputation',reputation,'title',title,'bossKills',boss_kills,'updatedAt',changed,
  'inspection',jsonb_build_object('userId',u::text,'heroId',hero_id,'sex',sex,'child',child,'level',lvl,'realm',realm,'realmIndex',realm_idx,'mapId',left(coalesce(snapshot->>'mapId','dai_thua_vien'),50),
   'rank',sect_rank,'pkMode',case when p->>'pkMode' in ('sect','all') then p->>'pkMode' else 'peace' end,
   'stats',jsonb_build_object('maxHp',hp,'maxMp',mp,'atk',atk,'def',def,'critRate',0.15,'critMul',1.8,'speed',190),
   'hp',floor(game_rank_private.num(p->'hp',0,hp)),'mp',floor(game_rank_private.num(p->'mp',0,mp)),'power',power,
   'equipment',equipment,'skills',skills,'mounts',mounts,'companions',companions,
   'friendCount',least(30,jsonb_array_length(game_rank_private.arr(p->'friends'))),
   'progress',jsonb_build_object('clears',clears,'explored',least(10000000,jsonb_array_length(game_rank_private.arr(p#>'{world,discovered}'))),
    'gathered',game_rank_private.total(p#>'{immortal,gathered}'),'crafted',game_rank_private.total(p#>'{immortal,crafted}'),
    'missions',case when game_rank_private.num(a->'missionDay',0,10000000) = floor(extract(epoch from changed+interval '7 hours')/86400) then jsonb_array_length(game_rank_private.arr(a->'completedMissions')) else 0 end))
  || case when child then '{}'::jsonb else jsonb_build_object('sect',sect) end);
end $$;

create or replace function game_rank_private.refresh_entry(u uuid,snapshot jsonb,changed timestamptz) returns void
language plpgsql set search_path='' as $$
declare projected jsonb;
begin
 projected := game_rank_private.project(u,snapshot,changed);
 if projected is null then delete from game_rank_private.entries where user_id=u;return;end if;
 insert into game_rank_private.entries(user_id,name_search,level,power,realm_score,contribution,dungeon_clears,pets_score,boss_kills,entry,updated_at)
 values(u,game_rank_private.fold(projected->>'name'),(projected#>>'{inspection,level}')::integer,(projected#>>'{inspection,power}')::bigint,
  case when (projected#>>'{inspection,child}')::boolean then 0 else ((projected#>>'{inspection,realmIndex}')::bigint+1)*1000+(projected#>>'{inspection,level}')::bigint end,
  (projected->>'contribution')::bigint,(projected#>>'{inspection,progress,clears}')::bigint,
  coalesce((select sum((v->>'rank')::bigint+(v->>'evolution')::bigint*3) from jsonb_array_elements(projected#>'{inspection,companions}') v),0),
  (projected->>'bossKills')::bigint,projected,changed)
 on conflict(user_id) do update set name_search=excluded.name_search,level=excluded.level,power=excluded.power,realm_score=excluded.realm_score,
  contribution=excluded.contribution,dungeon_clears=excluded.dungeon_clears,pets_score=excluded.pets_score,boss_kills=excluded.boss_kills,entry=excluded.entry,updated_at=excluded.updated_at;
end $$;
create or replace function game_rank_private.sync_save() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_op='DELETE' then delete from game_rank_private.entries where user_id=old.user_id;return old;end if;
 perform game_rank_private.refresh_entry(new.user_id,new.data,new.updated_at);
 return new;
end $$;
drop trigger if exists game_ranking_save on public.saves;
create trigger game_ranking_save after insert or update of data or delete on public.saves for each row execute function game_rank_private.sync_save();

-- Granting/revoking a premium item also refreshes an offline character's public stats.
create or replace function game_rank_private.sync_entitlement() returns trigger
language plpgsql security definer set search_path='' as $$
declare saved record; u uuid;
begin
 u:=case when tg_op='DELETE' then old.user_id else new.user_id end;
 for saved in select data,updated_at from public.saves where user_id=u loop
  perform game_rank_private.refresh_entry(u,saved.data,saved.updated_at);
 end loop;
 if tg_op='DELETE' then return old;end if;return new;
end $$;
do $$ begin
 if to_regclass('public.premium_entitlements') is not null then
  execute 'drop trigger if exists game_ranking_entitlement on public.premium_entitlements';
  execute 'create trigger game_ranking_entitlement after insert or delete on public.premium_entitlements for each row execute function game_rank_private.sync_entitlement()';
 end if;
end $$;

create index if not exists ranking_power on game_rank_private.entries(power desc,level desc,user_id);
create index if not exists ranking_level on game_rank_private.entries(level desc,user_id);
create index if not exists ranking_realm on game_rank_private.entries(realm_score desc,level desc,user_id);
create index if not exists ranking_sect on game_rank_private.entries(contribution desc,level desc,user_id);
create index if not exists ranking_dungeons on game_rank_private.entries(dungeon_clears desc,level desc,user_id);
create index if not exists ranking_pets on game_rank_private.entries(pets_score desc,level desc,user_id);
create index if not exists ranking_boss on game_rank_private.entries(boss_kills desc,level desc,user_id);

create or replace function public.game_leaderboard(p_instance_id uuid,p_category text default 'power',p_query text default '',p_offset integer default 0,p_limit integer default 8)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare score_col text; block_clause text; result jsonb; own uuid:=auth.uid(); skip integer:=greatest(0,least(100000,coalesce(p_offset,0))); page_size integer:=greatest(1,least(20,coalesce(p_limit,8)));
begin
 if own is null or not public.check_game_session(p_instance_id) then raise exception 'SESSION_REPLACED'; end if;
 if not game_rank_private.visible(own) then raise exception 'GAME_ACCESS_BLOCKED';end if;
 score_col := case p_category when 'power' then 'power' when 'level' then 'level' when 'realm' then 'realm_score' when 'sect' then 'contribution' when 'dungeons' then 'dungeon_clears' when 'pets' then 'pets_score' when 'boss' then 'boss_kills' else null end;
 if p_category='elements' then return jsonb_build_object('category',p_category,'supported',false,'population',0,'total',0,'offset',0,'limit',page_size,'top','[]'::jsonb,'rows','[]'::jsonb,'self',null,'serverTime',current_timestamp); end if;
 if score_col is null then raise exception 'INVALID_RANKING_CATEGORY'; end if;
 block_clause:=case when to_regclass('public.game_account_blocks') is null then '' else 'and not exists(select 1 from public.game_account_blocks blocked where blocked.user_id=e.user_id)' end;
 execute format($query$
  with ranked as materialized (
   select user_id,name_search,entry,row_number() over(order by %1$I desc,level desc,user_id) as rank
   from game_rank_private.entries e join auth.users au on au.id=e.user_id
   where (au.banned_until is null or au.banned_until<=current_timestamp) %2$s and (%1$I>0 or $1 in ('power','level','realm'))
  ), filtered as (select * from ranked where strpos(name_search,game_rank_private.fold($2))>0),
  page as (select * from filtered order by rank offset $3 limit $4)
  select jsonb_build_object('category',$1,'supported',true,'population',(select count(*) from ranked),'total',(select count(*) from filtered),
   'offset',$3,'limit',$4,'serverTime',current_timestamp,
   'top',coalesce((select jsonb_agg(jsonb_build_object('rank',rank,'entry',entry) order by rank) from ranked where rank<=3),'[]'::jsonb),
   'rows',coalesce((select jsonb_agg(jsonb_build_object('rank',rank,'entry',entry) order by rank) from page),'[]'::jsonb),
   'self',(select jsonb_build_object('rank',(select rank from ranked where user_id=$5),'entry',entry) from game_rank_private.entries where user_id=$5))
 $query$,score_col,block_clause) into result using p_category,left(btrim(coalesce(p_query,'')),32),skip,page_size,own;
 return result;
end $$;
revoke all on all functions in schema game_rank_private from public,anon,authenticated;
revoke all on function public.game_leaderboard(uuid,text,text,integer,integer) from public,anon,authenticated;
grant execute on function public.game_leaderboard(uuid,text,text,integer,integer) to authenticated;

-- Backfill offline characters without writing their private saves or changing timestamps.
do $$ declare saved record;begin
 for saved in select user_id,data,updated_at from public.saves loop
  perform game_rank_private.refresh_entry(saved.user_id,saved.data,saved.updated_at);
 end loop;
end $$;
notify pgrst,'reload schema';

create or replace function public.claim_game_mail(p_mail uuid,p_instance_id uuid) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=auth.uid(); lease public.game_sessions; s public.saves; m public.game_mail;
 p jsonb; inv jsonb; next_data jsonb; item text; amount jsonb; meta jsonb; qty integer; n bigint; key text; revision integer;
begin
 if u is null then raise exception 'LOGIN_REQUIRED';end if;
 -- Match the normal save lock order; serialize admin edits, saves, and claims for this account.
 perform pg_advisory_xact_lock(hashtextextended(u::text,42));
 select * into lease from public.game_sessions where user_id=u for update;
 if not found or lease.instance_id is distinct from p_instance_id or lease.auth_session_id is distinct from (auth.jwt()->>'session_id') or not public.game_access_allowed(u) then raise exception 'SESSION_REPLACED';end if;
 select * into s from public.saves where user_id=u for update;
 if not found then raise exception 'SAVE_NOT_FOUND';end if;
 select * into m from public.game_mail where id=p_mail and user_id=u for update;
 if not found then raise exception 'MAIL_NOT_FOUND';end if;
 if m.campaign_id='alphatest-v1' then return public.claim_alphatest_mail(p_mail,p_instance_id);end if;
 if m.campaign_id not like 'admin-grant:%' and m.campaign_id not like 'activity:%' then raise exception 'MAIL_NOT_CLAIMABLE';end if;
 if m.claimed_at is not null then return jsonb_build_object('already_claimed',true,'snapshot',s.data,'premium',public.premium_status(),'mail',to_jsonb(m)-'user_id'-'receipt');end if;
 if jsonb_typeof(m.rewards->'items') is distinct from 'object' then raise exception 'INVALID_MAIL_REWARDS';end if;
 p:=s.data->'player';
 if jsonb_typeof(p) is distinct from 'object' then raise exception 'INVALID_REWARD_SAVE';end if;
 inv:=case when jsonb_typeof(p->'inventory')='object' then p->'inventory' else '{}'::jsonb end;
 for item,amount in select part.key,part.value from jsonb_each(m.rewards->'items') part loop
  select data into meta from public.game_admin_catalog where kind='item' and id=item;
  if meta is null or jsonb_typeof(amount) is distinct from 'number' or amount::text!~'^\d{1,6}$' then raise exception 'INVALID_MAIL_REWARDS';end if;
  qty:=amount::text::integer;
  if qty not between 1 and 100000 or (meta ? 'slot' and qty>100) then raise exception 'INVALID_MAIL_REWARDS';end if;
  if item='linh_khi' then
   if coalesce(p->>'linhKhi','0')!~'^\d{1,15}$' then raise exception 'INVALID_REWARD_SAVE';end if;
   p:=p||jsonb_build_object('linhKhi',coalesce((p->>'linhKhi')::bigint,0)+qty);
  elsif item='tien_phap_bao' then
   if qty<>1 then raise exception 'INVALID_MAIL_REWARDS';end if;
   insert into public.premium_entitlements(user_id,item_id) values(u,item) on conflict do nothing;
   inv:=inv||jsonb_build_object(item,1);
  elsif meta ? 'slot' then
   for n in 1..qty loop key:=item||'~'||replace(gen_random_uuid()::text,'-','');inv:=inv||jsonb_build_object(key,1);end loop;
  else
   if coalesce(inv->>item,'0')!~'^\d{1,9}$' then raise exception 'INVALID_REWARD_SAVE';end if;
   n:=coalesce((inv->>item)::bigint,0)+qty;
   if n>999999999 then raise exception 'INVALID_QUANTITY';end if;
   inv:=inv||jsonb_build_object(item,n);
  end if;
 end loop;
 revision:=s.mail_reward_revision+1;
 p:=p||jsonb_build_object('inventory',inv,'mailRevision',revision);
 next_data:=jsonb_set(s.data,'{player}',p)||jsonb_build_object('savedAt',floor(extract(epoch from clock_timestamp())*1000));
 update public.saves set data=next_data,mail_reward_revision=revision,updated_at=clock_timestamp() where user_id=u returning * into s;
 update public.game_mail set claimed_at=clock_timestamp(),read_at=coalesce(read_at,clock_timestamp()),receipt=jsonb_build_object('revision',revision,'items',m.rewards->'items') where id=m.id returning * into m;
 return jsonb_build_object('already_claimed',false,'snapshot',s.data,'premium',public.premium_status(),'mail',to_jsonb(m)-'user_id'-'receipt');
end $$;
revoke all on function public.claim_game_mail(uuid,uuid) from public,anon,authenticated;
grant execute on function public.claim_game_mail(uuid,uuid) to authenticated;


-- Requires schema.sql, player-access.sql and leaderboard.sql. Safe to rerun.

create schema if not exists game_competitive;
revoke all on schema game_competitive from public,anon,authenticated;
create table if not exists game_competitive.ratings(
 season text not null,user_id uuid not null references auth.users(id) on delete cascade,
 rating integer not null default 1000,wins integer not null default 0,losses integer not null default 0,draws integer not null default 0,
 primary key(season,user_id));
create table if not exists game_competitive.queue(
 user_id uuid primary key references auth.users(id) on delete cascade,instance uuid not null,
 touched timestamptz not null default now(),realm integer not null,fighter jsonb not null);
create table if not exists game_competitive.matches(
 id uuid primary key default gen_random_uuid(),season text not null,a uuid not null references auth.users(id) on delete cascade,
 b uuid not null references auth.users(id) on delete cascade,fighters jsonb not null,created_at timestamptz not null default now(),
 expires_at timestamptz not null default now()+interval '3 minutes',reports jsonb not null default '{}',
 state text not null default 'playing',winner uuid,scored boolean not null default false,check(a<>b));
create index if not exists competitive_matches_a on game_competitive.matches(a,created_at desc);
alter table game_competitive.matches add column if not exists ready jsonb not null default '{}';
create index if not exists competitive_matches_b on game_competitive.matches(b,created_at desc);
alter table game_competitive.ratings enable row level security;
alter table game_competitive.queue enable row level security;
alter table game_competitive.matches enable row level security;

create or replace function game_competitive.settle(mid uuid) returns void language plpgsql security definer set search_path='' as $$
declare m game_competitive.matches; w uuid; eligible boolean;
begin
 select * into m from game_competitive.matches where id=mid for update;
 if not found or m.state<>'playing' or not(m.reports ? m.a::text and m.reports ? m.b::text) then return;end if;
 if m.reports->m.a::text<>m.reports->m.b::text then
  update game_competitive.matches set state='disputed' where id=mid;return;
 end if;
 w:=(m.reports->>m.a::text)::uuid;
 if w is not null and w not in(m.a,m.b) then raise exception 'INVALID_WINNER';end if;
 -- Two scored meetings per pair/day and 20 scored games per account/day.
 eligible:=(select count(*)<2 from game_competitive.matches where scored and created_at>=date_trunc('day',now() at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh' and ((a=m.a and b=m.b) or (a=m.b and b=m.a)));
 eligible:=eligible and (select count(*)<20 from game_competitive.matches where scored and created_at>=now()-interval '24 hours' and (a=m.a or b=m.a));
 eligible:=eligible and (select count(*)<20 from game_competitive.matches where scored and created_at>=now()-interval '24 hours' and (a=m.b or b=m.b));
 insert into game_competitive.ratings(season,user_id) values(m.season,m.a),(m.season,m.b) on conflict do nothing;
 if eligible then
  -- Stable lock order prevents cross-match deadlocks.
  perform 1 from game_competitive.ratings where season=m.season and user_id in(m.a,m.b) order by user_id for update;
  update game_competitive.ratings set rating=greatest(0,rating+case when w is null then 0 when w=user_id then 20 else -20 end),
   wins=wins+case when w=user_id then 1 else 0 end,losses=losses+case when w is not null and w<>user_id then 1 else 0 end,
   draws=draws+case when w is null then 1 else 0 end where season=m.season and user_id in(m.a,m.b);
 end if;
 update game_competitive.matches set state='finished',winner=w,scored=eligible where id=mid;
end $$;

create or replace function public.game_ranked(p_instance_id uuid,p_action text default 'status',p_payload jsonb default '{}')
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); ss text:=to_char(date_trunc('week',now() at time zone 'Asia/Ho_Chi_Minh'),'YYYY-MM-DD');
 m game_competitive.matches; peer game_competitive.queue; p jsonb; i jsonb; f jsonb; r game_competitive.ratings; rows jsonb; chosen uuid;
begin
 if u is null or not public.check_game_session(p_instance_id) then raise exception 'SESSION_REPLACED';end if;
 if p_action not in('status','join','poll','leave','report','ready') then raise exception 'INVALID_ACTION';end if;
 perform pg_advisory_xact_lock(738421911);
 delete from game_competitive.queue where touched<now()-interval '30 seconds';
 update game_competitive.matches set state='expired' where state='playing' and expires_at<now();
 select * into m from game_competitive.matches where state='playing' and (a=u or b=u) order by created_at desc limit 1 for update;
 if p_action='ready' then
  if m.id is not null and m.id::text=p_payload->>'id' then
   update game_competitive.matches set ready=ready||jsonb_build_object(u::text,extract(epoch from now())) where id=m.id;
  end if;
 elsif p_action='leave' then
  delete from game_competitive.queue where user_id=u;
  if m.id is not null then
   if not(m.ready ? m.a::text and m.ready ? m.b::text) then
    update game_competitive.matches set state='cancelled' where id=m.id;
   else
   chosen:=case when m.a=u then m.b else m.a end;
   update game_competitive.matches set reports=jsonb_build_object(m.a::text,chosen,m.b::text,chosen) where id=m.id;
   perform game_competitive.settle(m.id);
   end if;m:=null;
  end if;
 elsif p_action='report' then
  if m.id is not null and m.id::text=p_payload->>'id' then
   if not(m.ready ? m.a::text and m.ready ? m.b::text) then raise exception 'MATCH_NOT_STARTED';end if;
   if p_payload->>'winner' is not null and p_payload->>'winner' not in(m.a::text,m.b::text) then raise exception 'INVALID_WINNER';end if;
   if not(m.reports ? u::text) then update game_competitive.matches set reports=reports||jsonb_build_object(u::text,p_payload->'winner') where id=m.id;end if;
   perform game_competitive.settle(m.id);
  end if;
 elsif p_action='join' and m.id is null then
  select data into p from public.saves where user_id=u;
  i:=game_rank_private.project(u,p,now())->'inspection';
  if i is null or coalesce((i->>'child')::boolean,true) then raise exception 'ADMISSION_REQUIRED';end if;
  f:=jsonb_build_object('userId',u,'name',p#>>'{player,name}','heroId',i->'heroId','sex',i->'sex','level',i->'level','realm',i->'realm',
   'hp',i#>'{stats,maxHp}','maxHp',i#>'{stats,maxHp}','maxMp',i#>'{stats,maxMp}','atk',i#>'{stats,atk}','def',i#>'{stats,def}',
   'critRate',.15,'critMul',1.8,'speed',190,
   'loadout',(select jsonb_agg(value->'id') from jsonb_array_elements(i->'skills') where (value->>'equipped')::boolean and value->>'id'<>'than_phap'),
   'skillLevels',coalesce(p#>'{player,skills}','{}'::jsonb));
  insert into game_competitive.queue(user_id,instance,realm,fighter) values(u,p_instance_id,(i->>'realmIndex')::integer,f)
   on conflict(user_id) do update set instance=excluded.instance,touched=now(),realm=excluded.realm,fighter=excluded.fighter;
 end if;
 if p_action='poll' and m.id is not null and m.state='playing' and m.ready ? m.a::text and m.ready ? m.b::text then
  chosen:=case when m.a=u then m.b else m.a end;
  update game_competitive.matches set ready=ready||jsonb_build_object(u::text,extract(epoch from now())) where id=m.id;
  if extract(epoch from now())-(m.ready->>chosen::text)::numeric>30 then
   update game_competitive.matches set reports=jsonb_build_object(m.a::text,u,m.b::text,u) where id=m.id;
   perform game_competitive.settle(m.id);
  end if;
 end if;
 if p_action in('poll','join') and m.id is null then
  update game_competitive.queue set touched=now() where user_id=u and instance=p_instance_id;
  select q.* into peer from game_competitive.queue q join game_competitive.queue mine on mine.user_id=u
   where q.user_id<>u and abs(q.realm-mine.realm)<=1 and abs((q.fighter->>'level')::integer-(mine.fighter->>'level')::integer)<=15
   and exists(select 1 from public.game_sessions s where s.user_id=q.user_id and s.instance_id=q.instance)
   and game_rank_private.visible(q.user_id) and public.game_access_allowed(q.user_id)
   order by abs(q.realm-mine.realm),q.touched,q.user_id limit 1 for update of q;
  if peer.user_id is not null then
   select fighter into f from game_competitive.queue where user_id=u;
   insert into game_competitive.matches(season,a,b,fighters) values(ss,peer.user_id,u,jsonb_build_array(peer.fighter,f)) returning * into m;
   delete from game_competitive.queue where user_id in(u,peer.user_id);
  end if;
 end if;
 insert into game_competitive.ratings(season,user_id) values(ss,u) on conflict do nothing;
 select * into r from game_competitive.ratings where season=ss and user_id=u;
 select coalesce(jsonb_agg(x),'[]') into rows from(select t.user_id as "userId",coalesce(s.data#>>'{player,name}','Đạo hữu') name,t.rating,t.wins,t.losses,t.draws
  from game_competitive.ratings t join public.saves s on s.user_id=t.user_id where t.season=ss and game_rank_private.visible(t.user_id)
  order by t.rating desc,t.wins desc,t.user_id limit 50)x;
 select * into m from game_competitive.matches where (a=u or b=u) order by created_at desc limit 1;
 return jsonb_build_object('season',ss,'rating',r.rating,'wins',r.wins,'losses',r.losses,'draws',r.draws,'queue',exists(select 1 from game_competitive.queue where user_id=u),
  'match',case when m.state='playing' then jsonb_build_object('id',m.id,'a',m.fighters->0,'b',m.fighters->1,'expiresAt',m.expires_at) else null end,
  'status',coalesce(m.state,'idle'),'rows',rows,
  'result',case when m.id is not null and m.state<>'playing' then jsonb_build_object('id',m.id,'status',m.state,'winner',m.winner,'scored',m.scored) else null end);
end $$;
revoke all on all tables in schema game_competitive from public,anon,authenticated;
revoke all on all functions in schema game_competitive from public,anon,authenticated;
revoke all on function public.game_ranked(uuid,text,jsonb) from public,anon;
grant execute on function public.game_ranked(uuid,text,jsonb) to authenticated;
notify pgrst,'reload schema';

-- After competitive-play.sql, alphatest-mail.sql, admin-delivery.sql and admin-catalog.sql.

-- Upgrade the existing revision-safe item-mail claim function without weakening its locks.
do $upgrade$ declare body text; begin
 body:=pg_get_functiondef('public.claim_game_mail(uuid,uuid)'::regprocedure);
 if position('activity:%' in body)=0 then
  if position('if m.campaign_id not like ''admin-grant:%'' then' in body)=0 then raise exception 'Unsupported claim_game_mail version';end if;
  execute replace(body,'if m.campaign_id not like ''admin-grant:%'' then','if m.campaign_id not like ''admin-grant:%'' and m.campaign_id not like ''activity:%'' then');
 end if;
end $upgrade$;
create table if not exists game_competitive.activity_entries(
 user_id uuid not null references auth.users(id) on delete cascade,kind text not null,seed bigint not null,
 started_at timestamptz not null default now(),initial_bosses bigint not null,capture_at timestamptz,
 primary key(user_id,kind,seed),check(kind in('treasure','ruins')));
create table if not exists game_competitive.treasure_winners(
 seed bigint primary key,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now());
alter table game_competitive.activity_entries enable row level security;
alter table game_competitive.treasure_winners enable row level security;
create or replace function public.game_activity(p_instance_id uuid,p_kind text default 'treasure',p_action text default 'status',p_seed bigint default 0)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); epoch bigint:=floor(extract(epoch from now())); start_at bigint; duration integer; e game_competitive.activity_entries;
 bosses bigint; p jsonb; campaign text; loot jsonb; victor uuid; letter uuid;
begin
 if u is null or not public.check_game_session(p_instance_id) then raise exception 'SESSION_REPLACED';end if;
 if p_kind not in('treasure','ruins') or p_action not in('status','start','capture','cancel','claim','cache0','cache1') then raise exception 'INVALID_ACTION';end if;
 start_at:=floor((epoch+25200-case when p_kind='ruins' then 3600 else 0 end)::numeric/10800)*10800-25200+case when p_kind='ruins' then 3600 else 0 end;
 duration:=case when p_kind='ruins' then 2400 else 1500 end;
 if p_action='status' then return jsonb_build_object('now',epoch*1000,'winner',(select user_id from game_competitive.treasure_winners where seed=start_at));end if;
 if p_seed<>start_at or epoch>=start_at+duration then raise exception 'ACTIVITY_CLOSED';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_kind||p_seed::text,815));
 select data->'player' into p from public.saves where user_id=u;
 if p is null or coalesce(p->>'admitted','false')<>'true' then raise exception 'ADMISSION_REQUIRED';end if;
 bosses:=game_rank_private.num(p#>'{achievements,bossKills}',0,10000000);
 if p_action='start' then
  insert into game_competitive.activity_entries(user_id,kind,seed,initial_bosses) values(u,p_kind,p_seed,bosses) on conflict do nothing;
 end if;
 select * into e from game_competitive.activity_entries where user_id=u and kind=p_kind and seed=p_seed for update;
 if not found then raise exception 'ENTRY_REQUIRED';end if;
 if p_action='cancel' then update game_competitive.activity_entries set capture_at=null where user_id=u and kind=p_kind and seed=p_seed;end if;
 if p_action in('capture','claim') then
  if bosses<=e.initial_bosses or not coalesce(p->'activityVictories' ? (p_kind||':'||p_seed::text),false) or now()<e.started_at+interval '10 seconds' then raise exception 'GUARDIAN_REQUIRED';end if;
  if p_kind='treasure' and p_action='capture' then
   update game_competitive.activity_entries set capture_at=now() where user_id=u and kind=p_kind and seed=p_seed;
  end if;
 end if;
 if p_action in('claim','cache0','cache1') then
  if p_action like 'cache%' and p_kind<>'ruins' then raise exception 'INVALID_ACTION';end if;
  if p_action like 'cache%' and now()<e.started_at+interval '10 seconds' then raise exception 'EXPLORATION_REQUIRED';end if;
  if p_kind='treasure' then
   select user_id into victor from game_competitive.treasure_winners where seed=p_seed;
   if victor is not null and victor<>u then raise exception 'TREASURE_TAKEN';end if;
   if victor is null then
    if e.capture_at is null or now()<e.capture_at+interval '5 seconds' then raise exception 'CAPTURE_REQUIRED';end if;
    insert into game_competitive.treasure_winners(seed,user_id) values(p_seed,u);
   end if;
  end if;
  campaign:='activity:'||p_kind||':'||p_seed::text||':'||p_action||':'||u::text;
  if p_action like 'cache%' then loot:='{"linh_thach":20,"tinh_luyen_thach":1}'::jsonb;
  else
   loot:='{"linh_thach":150,"tinh_luyen_thach":3,"yeu_dan":2}'::jsonb;
   if random()<.015 then loot:=loot||'{"phap_bao_ngoc":1}'::jsonb;end if;
  end if;
  insert into public.game_mail_campaigns(id,enabled,title,body,rewards)
   values(campaign,false,case when p_kind='treasure' then 'Thiên Giáng Dị Bảo' else 'Kho báu Động Phủ Viễn Cổ' end,
    'Phần thưởng hoạt động đã được lưu. Đạo hữu hãy nhận tại đây.',jsonb_build_object('items',loot,'requiresAdmission',true)) on conflict do nothing;
  insert into public.game_mail(user_id,campaign_id,title,body,rewards)
   select u,id,title,body,rewards from public.game_mail_campaigns where id=campaign on conflict(user_id,campaign_id) do nothing;
  select id into letter from public.game_mail where user_id=u and campaign_id=campaign;
 end if;
 return jsonb_build_object('now',epoch*1000,'seed',p_seed,'mail',letter,'winner',(select user_id from game_competitive.treasure_winners where seed=p_seed));
end $$;
revoke all on game_competitive.activity_entries,game_competitive.treasure_winners from public,anon,authenticated;
revoke all on function public.game_activity(uuid,text,text,bigint) from public,anon;
grant execute on function public.game_activity(uuid,text,text,bigint) to authenticated;
notify pgrst,'reload schema';

-- Ngự Kiếm Vượt Thiên Quan v1. Requires the existing online sessions and leaderboard migrations.

create schema if not exists game_competitive;
revoke all on schema game_competitive from public,anon,authenticated;
create table if not exists game_competitive.sky_runs(
 user_id uuid primary key references auth.users(id) on delete cascade,
 id uuid not null unique default gen_random_uuid(),instance uuid not null,
 week text not null,seed bigint not null,started_at timestamptz not null default now(),result jsonb);
create table if not exists game_competitive.sky_best(
 week text not null,user_id uuid not null references auth.users(id) on delete cascade,
 score integer not null,energy integer not null,hits integer not null,achieved_at timestamptz not null default now(),
 primary key(week,user_id));
create index if not exists sky_best_week on game_competitive.sky_best(week,score,achieved_at,user_id);
alter table game_competitive.sky_runs enable row level security;
alter table game_competitive.sky_best enable row level security;
revoke all on game_competitive.sky_runs,game_competitive.sky_best from public,anon,authenticated;

-- Replay the actual steering/boost inputs. A client never supplies its score.
create or replace function game_competitive.sky_replay(seed bigint,inputs jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare
 rng bigint:=greatest(1,seed%2147483647); gx double precision[]:='{}'; hx double precision[]:='{}';
 seen boolean[]:=array_fill(false,array[9]); picked boolean[]:=array_fill(false,array[9]);
 x double precision:=0; distance double precision:=0; previous double precision;
 elapsed integer:=0; penalty integer:=0; energy integer:=0; hits integer:=0; gates integer:=0;
 charges integer:=3; shield integer:=0; boost_until integer:=0; cooldown integer:=0; slow_until integer:=0;
 total integer:=0; axis integer; boost integer; ticks integer; i integer; n integer; y integer; entry jsonb; finished boolean:=false;
begin
 if jsonb_typeof(inputs) is distinct from 'array' or jsonb_array_length(inputs) not between 1 and 3600 then raise exception 'REPLAY_INVALID';end if;
 for i in 1..9 loop
  rng:=(rng*16807)%2147483647;gx:=array_append(gx,((rng%5)-2)*.3::double precision);
  rng:=(rng*16807)%2147483647;hx:=array_append(hx,((rng%7)-3)*.25::double precision);
  rng:=(rng*16807)%2147483647;
 end loop;
 for entry in select value from jsonb_array_elements(inputs) loop
  if jsonb_typeof(entry) is distinct from 'array' or jsonb_array_length(entry)<>3 then raise exception 'REPLAY_INVALID';end if;
  if exists(select 1 from jsonb_array_elements(entry) v where jsonb_typeof(v)<>'number' or v::text !~ '^-?[0-9]+$') then raise exception 'REPLAY_INVALID';end if;
  axis:=(entry->>0)::integer;boost:=(entry->>1)::integer;ticks:=(entry->>2)::integer;
  total:=total+ticks;
  if abs(axis)>1000 or boost not in(0,1) or ticks not between 1 and 120 or total>3600 then raise exception 'REPLAY_INVALID';end if;
  for n in 1..ticks loop
   if finished or elapsed>=180000 then raise exception 'REPLAY_TRAILING';end if;
   elapsed:=elapsed+50;x:=greatest(-1,least(1,x+axis/1000::double precision*.022::double precision));
   if boost=1 and charges>0 and elapsed>=cooldown then charges:=charges-1;boost_until:=elapsed+1500;cooldown:=elapsed+5000;end if;
   previous:=distance;
   distance:=distance+5*(case when elapsed<boost_until then 1.65::double precision else 1 end)*(case when elapsed<slow_until then .55::double precision else 1 end);
   for i in 1..9 loop
    y:=i*500;
    if not seen[i] and previous<y-220 and distance>=y-220 then
     seen[i]:=true;
     if abs(x-hx[i])<.16::double precision then
      if shield>0 then shield:=shield-1;else hits:=hits+1;penalty:=penalty+2000;slow_until:=elapsed+700;end if;
     end if;
    end if;
    if not picked[i] and previous<y-110 and distance>=y-110 and abs(x-gx[i])<.2::double precision then
     picked[i]:=true;energy:=energy+1;if (i-1)%4=3 then shield:=1;end if;
    end if;
   end loop;
   if gates<9 and distance>=(gates+1)*500 then
    if abs(x-gx[gates+1])<=.23::double precision then gates:=gates+1;
    else distance:=(gates+1)*500-90;penalty:=penalty+2000;end if;
   end if;
   finished:=distance>=4800 and gates=9;
  end loop;
 end loop;
 if not finished then raise exception 'REPLAY_INCOMPLETE';end if;
 return jsonb_build_object('score',greatest(1000,elapsed+penalty-energy*250),'elapsed',elapsed,'energy',energy,'hits',hits,'penalty',penalty);
end $$;

create or replace function public.game_sky_race(p_instance_id uuid,p_action text default 'status',p_payload jsonb default '{}')
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 u uuid:=auth.uid(); start_week timestamptz:=date_trunc('week',now() at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh';
 current_week text:=to_char(start_week at time zone 'Asia/Ho_Chi_Minh','YYYY-MM-DD');
 current_seed bigint:=extract(epoch from start_week);run game_competitive.sky_runs; computed jsonb; rows jsonb; own_row jsonb; p jsonb;
begin
 if u is null or not public.check_game_session(p_instance_id) or not game_rank_private.visible(u) then raise exception 'SESSION_REPLACED';end if;
 if p_action not in('status','start','finish','cancel') then raise exception 'INVALID_ACTION';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text||':sky-race',0));
 if p_action='start' then
  select data->'player' into p from public.saves where user_id=u;
  if p is null or p->>'admitted' is distinct from 'true' then raise exception 'RUN_ADMISSION_REQUIRED';end if;
  insert into game_competitive.sky_runs(user_id,instance,week,seed) values(u,p_instance_id,current_week,current_seed)
  on conflict(user_id) do update set id=gen_random_uuid(),instance=excluded.instance,week=excluded.week,seed=excluded.seed,started_at=now(),result=null
  returning * into run;
 elsif p_action='finish' then
  select * into run from game_competitive.sky_runs where user_id=u for update;
  if not found or run.id::text is distinct from p_payload->>'id' or run.instance<>p_instance_id or run.week<>current_week or now()>run.started_at+interval '5 minutes' then raise exception 'RUN_EXPIRED';end if;
  if run.result is null then
   computed:=game_competitive.sky_replay(run.seed,p_payload->'inputs');
   if extract(epoch from now()-run.started_at)*1000<(computed->>'elapsed')::integer-1000 then raise exception 'RUN_TOO_FAST';end if;
   update game_competitive.sky_runs set result=computed where user_id=u returning * into run;
   insert into game_competitive.sky_best(week,user_id,score,energy,hits) values(current_week,u,(computed->>'score')::integer,(computed->>'energy')::integer,(computed->>'hits')::integer)
   on conflict(week,user_id) do update set score=excluded.score,energy=excluded.energy,hits=excluded.hits,achieved_at=now()
   where excluded.score<game_competitive.sky_best.score;
  end if;
 elsif p_action='cancel' then
  delete from game_competitive.sky_runs where user_id=u and id::text=p_payload->>'id' and result is null;
 end if;
 select coalesce(jsonb_agg(v order by score,achieved_at,user_id),'[]') into rows from (
  select b.score,b.achieved_at,b.user_id,jsonb_build_object('userId',b.user_id,'name',left(coalesce(s.data#>>'{player,name}','Đạo hữu'),24),'score',b.score,'energy',b.energy,'hits',b.hits) v
  from game_competitive.sky_best b join public.saves s on s.user_id=b.user_id where b.week=current_week and game_rank_private.visible(b.user_id)
  order by b.score,b.achieved_at,b.user_id limit 50) t;
 select jsonb_build_object('userId',u,'name',left(coalesce(s.data#>>'{player,name}','Đạo hữu'),24),'score',b.score,'energy',b.energy,'hits',b.hits)
 into own_row from game_competitive.sky_best b join public.saves s on s.user_id=b.user_id where b.week=current_week and b.user_id=u;
 return jsonb_build_object('week',current_week,'seed',current_seed,'rows',rows,'self',own_row,
  'run',case when p_action='start' then jsonb_build_object('id',run.id,'week',run.week,'seed',run.seed) else null end,
  'result',case when p_action='finish' then run.result else null end);
end $$;
revoke all on function game_competitive.sky_replay(bigint,jsonb) from public,anon,authenticated;
revoke all on function public.game_sky_race(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.game_sky_race(uuid,text,jsonb) to authenticated;
notify pgrst,'reload schema';

commit;
